class Solution {
    public boolean isValid(String s) {
        char[] st = new char[s.length()];
        int top = 0;
        for (int i = 0; i < s.length(); i++) {
            st[top++] = s.charAt(i);
            if (top >= 3 && st[top - 3] == 'a' && st[top - 2] == 'b' && st[top - 1] == 'c') {
                top -= 3;
            }
        }
        return top == 0;
    }
}

var isValid = function(s) {
    const st = [];
    for (let i = 0; i < s.length; i++) {
        st.push(s[i]);
        const len = st.length;
        if (len >= 3 && st[len - 3] === 'a' && st[len - 2] === 'b' && st[len - 1] === 'c') {
            st.pop();
            st.pop();
            st.pop();
        }
    }
    return st.length === 0;
};
